/* eslint-disable max-len, max-params */

'use strict';

// MODULES //

var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major' );
var dlaset = require( '@stdlib/lapack/base/dlaset' ).ndarray;
var dscal = require( '@stdlib/blas/base/dscal' ).ndarray;


// FUNCTIONS //

/**
* Scales a matrix `B` by a scalar `beta`.
*
* ## Notes
*
* -   As in the reference LAPACK implementation, `beta` is only ever `0` or `-1`. When `beta` is `0`, elements are explicitly assigned zero (as opposed to being multiplied by zero) in order to avoid propagating `NaN` and to match reference behavior.
*
* @private
* @param {NonNegativeInteger} N - number of rows in `B`
* @param {NonNegativeInteger} NRHS - number of columns in `B`
* @param {number} beta - scalar beta
* @param {Float64Array} B - input/output matrix `B`
* @param {integer} strideB1 - stride of the first dimension of `B`
* @param {integer} strideB2 - stride of the second dimension of `B`
* @param {NonNegativeInteger} offsetB - starting index of `B`
* @returns {Float64Array} `B`
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var B = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
*
* scale( 2, 2, -1.0, B, 2, 1, 0 );
* // B => <Float64Array>[ -1.0, -2.0, -3.0, -4.0 ]
*/
function scale( N, NRHS, beta, B, strideB1, strideB2, offsetB ) {
	var ib;
	var i;

	if ( beta === 0.0 ) {
		return dlaset( 'all', N, NRHS, 0.0, 0.0, B, strideB1, strideB2, offsetB );
	}
	// Case: beta === -1.0
	ib = offsetB;
	if ( isRowMajor( [ strideB1, strideB2 ] ) ) {
		// For row-major matrices, the last dimension has the fastest changing index, and, thus, scale row-by-row...
		for ( i = 0; i < N; i++ ) {
			dscal( NRHS, beta, B, strideB2, ib );
			ib += strideB1;
		}
		return B;
	}
	// For column-major matrices, the first dimension has the fastest changing index, and, thus, scale column-by-column...
	for ( i = 0; i < NRHS; i++ ) {
		dscal( N, beta, B, strideB1, ib );
		ib += strideB2;
	}
	return B;
}

/**
* Accumulates `s*A*X` into a row-major matrix `B`, where `A` is a tridiagonal matrix of order `N` and `N >= 2`.
*
* ## Notes
*
* -   In order to match the reference implementation, contributions are accumulated one term at a time in the same order in which they are accumulated in the reference implementation, thus ensuring identical floating-point rounding behavior.
* -   As `s` is either `1` or `-1`, multiplication by `s` is exact, and, thus, `B + (s*(a*x))` is equivalent to either `B + (a*x)` or `B - (a*x)`.
*
* @private
* @param {integer} N - order of the matrix `A`
* @param {NonNegativeInteger} NRHS - number of right hand sides (columns of `X` and `B`)
* @param {number} s - sign of the contribution of `A*X` (either `1` or `-1`)
* @param {Float64Array} DL - sub-diagonal of `A`
* @param {integer} strideDL - stride length for `DL`
* @param {NonNegativeInteger} offsetDL - starting index of `DL`
* @param {Float64Array} D - diagonal of `A`
* @param {integer} strideD - stride length for `D`
* @param {NonNegativeInteger} offsetD - starting index of `D`
* @param {Float64Array} DU - super-diagonal of `A`
* @param {integer} strideDU - stride length for `DU`
* @param {NonNegativeInteger} offsetDU - starting index of `DU`
* @param {Float64Array} X - input matrix `X`
* @param {integer} strideX1 - stride of the first dimension of `X`
* @param {integer} strideX2 - stride of the second dimension of `X`
* @param {NonNegativeInteger} offsetX - starting index of `X`
* @param {Float64Array} B - input/output matrix `B`
* @param {integer} strideB1 - stride of the first dimension of `B`
* @param {integer} strideB2 - stride of the second dimension of `B`
* @param {NonNegativeInteger} offsetB - starting index of `B`
* @returns {Float64Array} `B`
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var DL = new Float64Array( [ 1.0, 1.0 ] );
* var D = new Float64Array( [ 2.0, 3.0, 4.0 ] );
* var DU = new Float64Array( [ 1.0, 1.0 ] );
* var X = new Float64Array( [ 1.0, 1.0, 1.0 ] );
* var B = new Float64Array( [ 0.0, 0.0, 0.0 ] );
*
* rowMajor( 3, 1, 1.0, DL, 1, 0, D, 1, 0, DU, 1, 0, X, 1, 1, 0, B, 1, 1, 0 );
* // B => <Float64Array>[ 3.0, 5.0, 5.0 ]
*/
function rowMajor( N, NRHS, s, DL, strideDL, offsetDL, D, strideD, offsetD, DU, strideDU, offsetDU, X, strideX1, strideX2, offsetX, B, strideB1, strideB2, offsetB ) {
	var idl;
	var idu;
	var id;
	var jb;
	var jx;
	var ib;
	var ix;
	var i0;
	var i1;
	var v;

	ib = offsetB;
	ix = offsetX;
	idl = offsetDL;
	id = offsetD;
	idu = offsetDU;

	// First row:
	jb = ib;
	jx = ix;
	for ( i0 = 0; i0 < NRHS; i0++ ) {
		v = B[ jb ];
		v += s * ( D[ id ] * X[ jx ] );
		v += s * ( DU[ idu ] * X[ jx+strideX1 ] );
		B[ jb ] = v;
		jb += strideB2;
		jx += strideX2;
	}
	ib += strideB1;
	ix += strideX1;
	id += strideD;
	idu += strideDU;

	// Interior rows:
	for ( i1 = 1; i1 < N-1; i1++ ) {
		jb = ib;
		jx = ix;
		for ( i0 = 0; i0 < NRHS; i0++ ) {
			v = B[ jb ];
			v += s * ( DL[ idl ] * X[ jx-strideX1 ] );
			v += s * ( D[ id ] * X[ jx ] );
			v += s * ( DU[ idu ] * X[ jx+strideX1 ] );
			B[ jb ] = v;
			jb += strideB2;
			jx += strideX2;
		}
		ib += strideB1;
		ix += strideX1;
		idl += strideDL;
		id += strideD;
		idu += strideDU;
	}
	// Last row:
	jb = ib;
	jx = ix;
	for ( i0 = 0; i0 < NRHS; i0++ ) {
		v = B[ jb ];
		v += s * ( DL[ idl ] * X[ jx-strideX1 ] );
		v += s * ( D[ id ] * X[ jx ] );
		B[ jb ] = v;
		jb += strideB2;
		jx += strideX2;
	}
	return B;
}

/**
* Accumulates `s*A*X` into a column-major matrix `B`, where `A` is a tridiagonal matrix of order `N` and `N >= 2`.
*
* ## Notes
*
* -   In order to match the reference implementation, contributions are accumulated one term at a time in the same order in which they are accumulated in the reference implementation, thus ensuring identical floating-point rounding behavior.
* -   As `s` is either `1` or `-1`, multiplication by `s` is exact, and, thus, `B + (s*(a*x))` is equivalent to either `B + (a*x)` or `B - (a*x)`.
*
* @private
* @param {integer} N - order of the matrix `A`
* @param {NonNegativeInteger} NRHS - number of right hand sides (columns of `X` and `B`)
* @param {number} s - sign of the contribution of `A*X` (either `1` or `-1`)
* @param {Float64Array} DL - sub-diagonal of `A`
* @param {integer} strideDL - stride length for `DL`
* @param {NonNegativeInteger} offsetDL - starting index of `DL`
* @param {Float64Array} D - diagonal of `A`
* @param {integer} strideD - stride length for `D`
* @param {NonNegativeInteger} offsetD - starting index of `D`
* @param {Float64Array} DU - super-diagonal of `A`
* @param {integer} strideDU - stride length for `DU`
* @param {NonNegativeInteger} offsetDU - starting index of `DU`
* @param {Float64Array} X - input matrix `X`
* @param {integer} strideX1 - stride of the first dimension of `X`
* @param {integer} strideX2 - stride of the second dimension of `X`
* @param {NonNegativeInteger} offsetX - starting index of `X`
* @param {Float64Array} B - input/output matrix `B`
* @param {integer} strideB1 - stride of the first dimension of `B`
* @param {integer} strideB2 - stride of the second dimension of `B`
* @param {NonNegativeInteger} offsetB - starting index of `B`
* @returns {Float64Array} `B`
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var DL = new Float64Array( [ 1.0, 1.0 ] );
* var D = new Float64Array( [ 2.0, 3.0, 4.0 ] );
* var DU = new Float64Array( [ 1.0, 1.0 ] );
* var X = new Float64Array( [ 1.0, 1.0, 1.0 ] );
* var B = new Float64Array( [ 0.0, 0.0, 0.0 ] );
*
* columnMajor( 3, 1, 1.0, DL, 1, 0, D, 1, 0, DU, 1, 0, X, 1, 3, 0, B, 1, 3, 0 );
* // B => <Float64Array>[ 3.0, 5.0, 5.0 ]
*/
function columnMajor( N, NRHS, s, DL, strideDL, offsetDL, D, strideD, offsetD, DU, strideDU, offsetDU, X, strideX1, strideX2, offsetX, B, strideB1, strideB2, offsetB ) {
	var idl;
	var idu;
	var id;
	var jb;
	var jx;
	var ib;
	var ix;
	var i0;
	var i1;
	var v;

	ib = offsetB;
	ix = offsetX;
	for ( i1 = 0; i1 < NRHS; i1++ ) {
		idl = offsetDL;
		id = offsetD;
		idu = offsetDU;
		jb = ib;
		jx = ix;

		// First row:
		v = B[ jb ];
		v += s * ( D[ id ] * X[ jx ] );
		v += s * ( DU[ idu ] * X[ jx+strideX1 ] );
		B[ jb ] = v;
		jb += strideB1;
		jx += strideX1;
		id += strideD;
		idu += strideDU;

		// Interior rows:
		for ( i0 = 1; i0 < N-1; i0++ ) {
			v = B[ jb ];
			v += s * ( DL[ idl ] * X[ jx-strideX1 ] );
			v += s * ( D[ id ] * X[ jx ] );
			v += s * ( DU[ idu ] * X[ jx+strideX1 ] );
			B[ jb ] = v;
			jb += strideB1;
			jx += strideX1;
			idl += strideDL;
			id += strideD;
			idu += strideDU;
		}
		// Last row:
		v = B[ jb ];
		v += s * ( DL[ idl ] * X[ jx-strideX1 ] );
		v += s * ( D[ id ] * X[ jx ] );
		B[ jb ] = v;

		ib += strideB2;
		ix += strideX2;
	}
	return B;
}


// MAIN //

/**
* Performs a matrix-matrix product of the form `B := α*op(A)*X + β*B` where `op(A)` is either `op(A) = A` or `op(A) = A^T`, `α` and `β` are scalars, and `A` is a tridiagonal matrix.
*
* ## Notes
*
* -   `DL` should have `N-1` indexed elements representing the sub-diagonal of `A`.
* -   `D` should have `N` indexed elements representing the diagonal of `A`.
* -   `DU` should have `N-1` indexed elements representing the super-diagonal of `A`.
* -   `X` is an `N` by `NRHS` input matrix.
* -   `B` is an `N` by `NRHS` input/output matrix.
* -   `alpha` must be `0`, `1`, or `-1`; otherwise, it is assumed to be `0`.
* -   `beta` must be `0`, `1`, or `-1`; otherwise, it is assumed to be `1`.
*
* @private
* @param {string} trans - specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param {NonNegativeInteger} N - order of the matrix `A`
* @param {NonNegativeInteger} NRHS - number of right hand sides (columns of `X` and `B`)
* @param {number} alpha - scalar alpha
* @param {Float64Array} DL - sub-diagonal of `A`
* @param {integer} strideDL - stride length for `DL`
* @param {NonNegativeInteger} offsetDL - starting index of `DL`
* @param {Float64Array} D - diagonal of `A`
* @param {integer} strideD - stride length for `D`
* @param {NonNegativeInteger} offsetD - starting index of `D`
* @param {Float64Array} DU - super-diagonal of `A`
* @param {integer} strideDU - stride length for `DU`
* @param {NonNegativeInteger} offsetDU - starting index of `DU`
* @param {Float64Array} X - input matrix `X`
* @param {integer} strideX1 - stride of the first dimension of `X`
* @param {integer} strideX2 - stride of the second dimension of `X`
* @param {NonNegativeInteger} offsetX - starting index of `X`
* @param {number} beta - scalar beta
* @param {Float64Array} B - input/output matrix `B`
* @param {integer} strideB1 - stride of the first dimension of `B`
* @param {integer} strideB2 - stride of the second dimension of `B`
* @param {NonNegativeInteger} offsetB - starting index of `B`
* @returns {Float64Array} `B`
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var DL = new Float64Array( [ 1.0, 1.0 ] );
* var D = new Float64Array( [ 2.0, 3.0, 4.0 ] );
* var DU = new Float64Array( [ 1.0, 1.0 ] );
* var X = new Float64Array( [ 1.0, 1.0, 1.0 ] );
* var B = new Float64Array( [ 0.0, 0.0, 0.0 ] );
*
* dlagtm( 'no-transpose', 3, 1, 1.0, DL, 1, 0, D, 1, 0, DU, 1, 0, X, 1, 3, 0, 0.0, B, 1, 3, 0 );
* // B => <Float64Array>[ 3.0, 5.0, 5.0 ]
*/
function dlagtm( trans, N, NRHS, alpha, DL, strideDL, offsetDL, D, strideD, offsetD, DU, strideDU, offsetDU, X, strideX1, strideX2, offsetX, beta, B, strideB1, strideB2, offsetB ) {
	var sd1;
	var sd3;
	var od1;
	var od3;
	var d1;
	var d3;
	var ib;
	var ix;
	var i0;
	var s;
	var v;

	if ( N === 0 ) {
		return B;
	}
	// Multiply `B` by `beta`, noting that, as in the reference implementation, `B` is left unchanged whenever `beta` is neither `0` nor `-1` (i.e., `beta` is assumed to be `1`)...
	if ( beta === 0.0 || beta === -1.0 ) {
		scale( N, NRHS, beta, B, strideB1, strideB2, offsetB );
	}
	// Resolve the sign of the contribution of `A*X`, noting that, as in the reference implementation, `A*X` is not accumulated whenever `alpha` is neither `1` nor `-1` (i.e., `alpha` is assumed to be `0`)...
	if ( alpha === 1.0 ) {
		s = 1.0;
	} else if ( alpha === -1.0 ) {
		s = -1.0;
	} else {
		return B;
	}
	// Resolve the off-diagonals according to whether `A` should be transposed, noting that, for a real matrix, a conjugate transpose is equivalent to a transpose...
	if ( trans === 'no-transpose' ) {
		// B := B + s*A*X, where `DL` is the sub-diagonal and `DU` is the super-diagonal...
		d1 = DL;
		sd1 = strideDL;
		od1 = offsetDL;
		d3 = DU;
		sd3 = strideDU;
		od3 = offsetDU;
	} else {
		// B := B + s*A^T*X, where the roles of `DL` and `DU` are interchanged...
		d1 = DU;
		sd1 = strideDU;
		od1 = offsetDU;
		d3 = DL;
		sd3 = strideDL;
		od3 = offsetDL;
	}
	// Handle `N == 1` separately, as neither a sub-diagonal nor a super-diagonal contributes...
	if ( N === 1 ) {
		ib = offsetB;
		ix = offsetX;
		v = s * D[ offsetD ];
		for ( i0 = 0; i0 < NRHS; i0++ ) {
			B[ ib ] += v * X[ ix ];
			ib += strideB2;
			ix += strideX2;
		}
		return B;
	}
	// Case: N >= 2
	if ( isRowMajor( [ strideB1, strideB2 ] ) ) {
		return rowMajor( N, NRHS, s, d1, sd1, od1, D, strideD, offsetD, d3, sd3, od3, X, strideX1, strideX2, offsetX, B, strideB1, strideB2, offsetB );
	}
	return columnMajor( N, NRHS, s, d1, sd1, od1, D, strideD, offsetD, d3, sd3, od3, X, strideX1, strideX2, offsetX, B, strideB1, strideB2, offsetB );
}


// EXPORTS //

module.exports = dlagtm;
